package br.com.inpetu.android;

import android.app.*;
import android.os.*;
import android.content.*;
import android.graphics.Color;
import android.graphics.Typeface;
import android.graphics.drawable.GradientDrawable;
import android.text.InputType;
import android.text.method.*;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.text.NumberFormat;
import java.time.*;
import java.util.*;

public final class MainActivity extends Activity {
 private Store store;
 private LinearLayout page;
 private LocalDate selected=LocalDate.now();
 private String exportText="";
 private static final int BLUE=0xff087fc5,INK=0xff203449,MUTED=0xff61758a;
 private final NumberFormat money=NumberFormat.getCurrencyInstance(new Locale("pt","BR"));
 @Override public void onCreate(Bundle saved){super.onCreate(saved);showLoading();new Thread(()->{try{Store ready=new Store(this);runOnUiThread(()->{if(isFinishing()||isDestroyed()){ready.close();return;}store=ready;store.event("INFO","APP_STARTED",0,null);installCrashHandler();loginPage();});}catch(Exception e){runOnUiThread(()->new AlertDialog.Builder(this).setTitle("Não foi possível abrir").setMessage("Se já houver dados neste celular, não desinstale. O banco foi preservado. Procure a equipe do projeto.").setPositiveButton("Fechar",(d,w)->finish()).show());}},"inpetu-db").start();}
 private void installCrashHandler(){Thread.UncaughtExceptionHandler original=Thread.getDefaultUncaughtExceptionHandler();Thread.setDefaultUncaughtExceptionHandler((t,e)->{try{store.event("ERROR","UNCAUGHT_FAILURE",0,e);}catch(Exception ignored){}if(original!=null)original.uncaughtException(t,e);});}
 private int dp(int n){return Math.round(getResources().getDisplayMetrics().density*n);}
 private void showLoading(){TextView t=new TextView(this);t.setText("InPETU Hub\nPreparando o aplicativo experimental…");t.setTextSize(24);t.setGravity(Gravity.CENTER);setContentView(t);}
 private GradientDrawable bg(int color){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(12));return d;}
 private TextView label(String text,int size,int color){TextView v=new TextView(this);v.setText(text);v.setTextSize(size);v.setTextColor(color);v.setPadding(0,dp(5),0,dp(5));return v;}
 private void begin(String title){ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);scroll.setBackgroundColor(0xfff3f7fa);page=new LinearLayout(this);page.setOrientation(LinearLayout.VERTICAL);page.setPadding(dp(20),dp(20),dp(20),dp(32));scroll.addView(page);setContentView(scroll);
  // Insets respeitados em Android 15+; inclui navegação por gestos e recortes.
  scroll.setOnApplyWindowInsetsListener((v,insets)->{v.setPadding(insets.getSystemWindowInsetLeft(),insets.getSystemWindowInsetTop(),insets.getSystemWindowInsetRight(),insets.getSystemWindowInsetBottom());return insets;});scroll.requestApplyInsets();
  TextView brand=label("InPETU Hub",30,INK);brand.setTypeface(null,Typeface.BOLD);page.addView(brand);
  TextView badge=label("  ANDROID EXPERIMENTAL · "+Store.VERSION+"  ",12,0xff775400);badge.setBackground(bg(0xffffe8aa));page.addView(badge);
  page.addView(label("Funciona offline • dados somente neste celular",13,MUTED));page.addView(label(title,24,INK));
  if(store!=null&&store.logged()){page.addView(label(store.name()+" · "+(store.admin()?"Administrador":"Colaborador"),13,MUTED));LinearLayout nav=new LinearLayout(this);for(String name:new String[]{"Agenda","Espaços","Mais"}){Button b=new Button(this);b.setText(name);b.setAllCaps(false);nav.addView(b,new LinearLayout.LayoutParams(0,dp(52),1));b.setOnClickListener(v->{if(name.equals("Agenda"))agenda();else if(name.equals("Espaços"))spaces();else menu();});}page.addView(nav);}
  if(store!=null)store.event("INFO","SCREEN_OPENED",0,null);
 }
 private void note(String message){page.addView(label(message,14,MUTED));}
 private void title(String message){TextView t=label(message,19,INK);t.setTypeface(null,Typeface.BOLD);page.addView(t);}
 private Button button(String text,Runnable action){Button b=new Button(this);b.setText(text);b.setAllCaps(false);b.setTextColor(Color.WHITE);b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(BLUE));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(52));p.setMargins(0,dp(8),0,dp(4));page.addView(b,p);b.setOnClickListener(v->attempt(action));return b;}
 private void attempt(Runnable action){try{action.run();}catch(Exception e){try{store.event(e instanceof IllegalArgumentException?"WARN":"ERROR",e instanceof IllegalArgumentException?"ACTION_REJECTED":"ACTION_FAILED",0,e);}catch(Exception ignored){}new AlertDialog.Builder(this).setTitle("Confira os dados").setMessage(e instanceof IllegalArgumentException?e.getMessage():"Não foi possível concluir. Os dados já salvos foram preservados; confira os logs locais.").setPositiveButton("Entendi",null).show();}}
 private EditText field(String name,String value,int type){page.addView(label(name,14,INK));EditText input=new EditText(this);input.setSingleLine(true);input.setText(value);input.setInputType(type);input.setTextColor(INK);input.setTextSize(16);input.setBackground(bg(Color.WHITE));input.setPadding(dp(12),dp(12),dp(12),dp(12));input.setContentDescription(name);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(52));p.setMargins(0,0,0,dp(8));page.addView(input,p);return input;}
 private EditText field(String name,String value){return field(name,value,InputType.TYPE_CLASS_TEXT);}
 private String value(EditText input){return input.getText().toString();}
 private CheckBox check(String name,boolean checked){CheckBox c=new CheckBox(this);c.setText(name);c.setChecked(checked);c.setTextColor(INK);page.addView(c);return c;}
 private Spinner select(String name,String[] items,int index){page.addView(label(name,14,INK));Spinner s=new Spinner(this);ArrayAdapter<String> adapter=new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,items);s.setAdapter(adapter);s.setSelection(Math.max(0,index));page.addView(s,new LinearLayout.LayoutParams(-1,dp(52)));return s;}
 private Button dayPicker(LocalDate day,java.util.function.Consumer<LocalDate> result){Button b=button("Data: "+day.toString(),()->{});final LocalDate[] date={day};b.setOnClickListener(v->{DatePickerDialog dialog=new DatePickerDialog(this,(picker,y,m,d)->{date[0]=LocalDate.of(y,m+1,d);b.setText("Data: "+date[0]);result.accept(date[0]);},date[0].getYear(),date[0].getMonthValue()-1,date[0].getDayOfMonth());dialog.show();});return b;}
 private void reason(String title,java.util.function.Consumer<String> action){EditText text=new EditText(this);text.setHint("Justificativa obrigatória");new AlertDialog.Builder(this).setTitle(title).setView(text).setPositiveButton("Confirmar",(d,w)->attempt(()->action.accept(value(text)))).setNegativeButton("Voltar",null).show();}
 private String amount(long cents){return money.format(cents/100.0);}
 private String rawMoney(JSONObject c,String key){return c.isNull(key)?"":String.format(Locale.ROOT,"%.2f",c.optLong(key)/100.0);}
 private void loginPage(){begin("Área interna");note("Instalação experimental de demonstração. Não use dados confidenciais. Os cinco acessos são os mesmos do desktop.");EditText login=field("Login *",""),password=field("Senha *","",InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);password.setTransformationMethod(PasswordTransformationMethod.getInstance());CheckBox show=check("Mostrar senha",false);show.setOnCheckedChangeListener((v,on)->password.setTransformationMethod(on?HideReturnsTransformationMethod.getInstance():PasswordTransformationMethod.getInstance()));button("Entrar",()->{if(!store.login(value(login),value(password)))throw new IllegalArgumentException("Login ou senha inválidos.");agenda();});note("Acessos de demonstração: milena, bernardo, joaof, joaoe e guilherme. Consulte o guia da release para as senhas.");}
 private void agenda(){begin("Agenda local");dayPicker(selected,day->{selected=day;agenda();});note("Apenas reservas aprovadas ocupam horários. Pendentes expiram em 24 horas.");List<JSONObject> spaces=store.spaces(),bookings=store.bookings(selected);if(spaces.isEmpty())note("Sem espaços cadastrados. Abra Espaços para começar.");for(JSONObject space:spaces){if(space.optInt("active")!=1||space.optInt("available")!=1)continue;title(space.optString("name")+" · "+space.optInt("capacity")+" pessoas");List<JSONObject> occupied=new ArrayList<>();for(JSONObject b:bookings)if(b.optLong("space")==space.optLong("id")&&b.optString("status").equals("APROVADA"))occupied.add(b);if(occupied.isEmpty())note("Livre no expediente configurado.");else for(JSONObject b:occupied)button(Rules.time(b.optInt("start"))+"–"+Rules.time(b.optInt("end"))+" · "+b.optString("title"),()->detail(b.optLong("id")));}
  button("Nova reserva",()->newBooking(selected));title("Reservas deste dia");if(bookings.isEmpty())note("Nenhuma reserva neste dia.");for(JSONObject b:bookings)button("#"+b.optLong("id")+" · "+b.optString("title")+" · "+b.optString("status"),()->detail(b.optLong("id")));}
 private void spaces(){begin("Espaços");button("Cadastrar espaço",()->editSpace(null));for(JSONObject s:store.spaces())button(s.optString("name")+" · "+s.optInt("capacity")+" pessoas"+(s.optInt("active")==0?" · Inativo":""),()->editSpace(s));}
 private void editSpace(JSONObject space){begin(space==null?"Novo espaço":"Editar espaço");EditText name=field("Nome do espaço *",space==null?"":space.optString("name")),capacity=field("Capacidade (inteiro positivo) *",space==null?"":space.optString("capacity"),InputType.TYPE_CLASS_NUMBER);CheckBox active=check("Ativo",space==null||space.optInt("active")==1),available=check("Disponível para reservas",space==null||space.optInt("available")==1);button("Salvar espaço",()->{store.saveSpace(space==null?null:space.optLong("id"),value(name),value(capacity),active.isChecked(),available.isChecked());spaces();});}
 private void newBooking(LocalDate date){begin("Nova reserva");List<JSONObject> spaces=new ArrayList<>();for(JSONObject s:store.spaces())if(s.optInt("active")==1&&s.optInt("available")==1)spaces.add(s);if(spaces.isEmpty()){note("Cadastre e habilite um espaço antes de reservar.");return;}final LocalDate[] chosen={date};dayPicker(date,d->chosen[0]=d);String[] labels=new String[spaces.size()];for(int i=0;i<labels.length;i++)labels[i]=spaces.get(i).optString("name")+" · "+spaces.get(i).optInt("capacity")+" pessoas";Spinner space=select("Espaço *",labels,0);JSONObject config=store.config();EditText start=field("Início (HH:mm) *",Rules.time(config.optInt("opening"))),end=field("Fim (HH:mm) *",Rules.time(Math.min(config.optInt("closing"),config.optInt("opening")+60)));EditText title=field("Nome do evento *",""),person=field("Nome do solicitante *",""),cnpj=field("CNPJ (14 dígitos) *","",InputType.TYPE_CLASS_NUMBER),email=field("Email *","",InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_EMAIL_ADDRESS),phone=field("Telefone *","",InputType.TYPE_CLASS_PHONE),company=field("Empresa/instituição *",""),city=field("Cidade *",""),count=field("Participantes *","1",InputType.TYPE_CLASS_NUMBER);List<JSONObject> personas=store.rows("SELECT * FROM personas ORDER BY code");String[] personasText=new String[personas.size()];for(int i=0;i<personasText.length;i++)personasText[i]=personas.get(i).optString("code")+" · "+personas.get(i).optString("name");Spinner persona=select("Persona declarada *",personasText,5);CheckBox paid=check("Inscrição paga",false),financed=check("Atividade financiada",false),academic=check("Atividade acadêmica (P2)",false);note("A reserva fica pendente até a conferência e aprovação. Valores são calculados usando a tabela local, que deve ser revisada pela equipe.");button("Salvar solicitação",()->{try{JSONObject b=new JSONObject().put("space",spaces.get(space.getSelectedItemPosition()).optLong("id")).put("day",chosen[0].toString()).put("start",Rules.minute(value(start))).put("end",Rules.minute(value(end))).put("title",value(title)).put("person",value(person)).put("cnpj",value(cnpj)).put("email",value(email)).put("phone",value(phone)).put("company",value(company)).put("city",value(city)).put("participants",Rules.integer(value(count),"Participantes")).put("persona",personas.get(persona.getSelectedItemPosition()).optString("code")).put("paid",paid.isChecked()?1:0).put("academic",academic.isChecked()?1:0).put("financed",financed.isChecked()?1:0);long id=store.createBooking(b);selected=chosen[0];detail(id);}catch(JSONException e){throw new IllegalArgumentException("Confira os campos.");}});}
 private void detail(long id){JSONObject b=store.booking(id);begin("Reserva #"+id);title(b.optString("title"));note(b.optString("day")+" · "+Rules.time(b.optInt("start"))+"–"+Rules.time(b.optInt("end")));note(b.optString("space_name")+" · "+b.optInt("participants")+" participantes");note("Situação: "+b.optString("status")+" · Pagamento: "+b.optString("payment"));note(b.optString("person")+" · "+b.optString("company")+" · "+b.optString("city"));note(b.optString("email")+" · "+b.optString("phone")+" · CNPJ "+b.optString("cnpj"));note("Persona: "+b.optString("persona")+" · Uso de cota: "+(b.optInt("uses_quota")==1?b.optInt("quota_minutes")+" minutos":"Não"));title("Valores registrados");note("Total: "+amount(b.optLong("amount"))+" · Sinal ("+b.optInt("deposit_pct")+"%): "+amount(b.optLong("deposit"))+" · Restante: "+amount(b.optLong("amount")-b.optLong("deposit")));note("A aprovação recalcula valores e verifica taxas, disponibilidade e cotas. Pagamentos são conferidos manualmente; este app não cobra nem envia emails.");String status=b.optString("status");if(status.equals("PENDENTE")){CheckBox identity=check("Conferi o vínculo com a instituição",false);button("Aprovar reserva",()->{store.approve(id,identity.isChecked());detail(id);});button("Recusar",()->reason("Motivo da recusa",reason->{store.reject(id,reason);detail(id);}));}if(status.equals("PENDENTE")||status.equals("APROVADA")){button("Cancelar reserva",()->reason("Cancelar reserva",reason->{store.cancel(id,reason,false);detail(id);}));if(store.admin())button("Cancelar por força maior",()->reason("Justificativa de força maior",reason->{store.cancel(id,reason,true);detail(id);}));}if(status.equals("APROVADA")||status.equals("CONCLUIDA")){String[] states={"PENDENTE","SINAL_PAGO","PAGO"};button("Registrar pagamento",()->new AlertDialog.Builder(this).setTitle("Conferência manual").setItems(states,(d,index)->attempt(()->{store.payment(id,states[index]);detail(id);})).show());}if(status.equals("APROVADA"))button("Concluir evento",()->{store.complete(id);detail(id);});if(!b.optString("reason").isEmpty())note("Justificativa: "+b.optString("reason"));}
 private void menu(){begin("Mais opções");button("Cotas mensais",this::quotas);button("Logs locais",this::logs);if(store.admin()){button("Configurar expediente e taxas",this::settings);button("Tabela de preços",this::prices);button("Cadastrar feriado",this::holiday);button("Exportar backup privado",()->export("inpetu-android-backup.json",store.backup()));button("Restaurar backup numa instalação vazia",()->new AlertDialog.Builder(this).setTitle("Restaurar backup").setMessage("Permitido somente se não houver espaços nem reservas. Seus dados atuais não serão substituídos. Contas e senhas não são importadas.").setPositiveButton("Escolher arquivo",(d,w)->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("application/json");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,12);}).setNegativeButton("Voltar",null).show());}title("Sobre esta versão");note("Android "+Store.VERSION+" — experimental e independente. Não sincroniza com computadores ou outros celulares. Não contém CRM de atendimentos/visitas, edição de reserva, SMTP ou atualização automática. Os logs ficam neste aparelho e podem ser exportados.");button("Sair da conta",()->{store.logout();loginPage();});}
 private void settings(){begin("Expediente e taxas");JSONObject c=store.config();EditText open=field("Abertura (HH:mm) *",Rules.time(c.optInt("opening"))),close=field("Fechamento (HH:mm) *",Rules.time(c.optInt("closing"))),hours=field("Horas por turno *",c.optString("hours"),InputType.TYPE_CLASS_NUMBER),operation=field("Operação (R$) *",rawMoney(c,"operation")),cleaning=field("Limpeza (R$) *",rawMoney(c,"cleaning")),supplies=field("Insumos de limpeza P2 (R$) *",rawMoney(c,"supplies"));note("Use valores aprovados pelo Hub. Informe 0,00 explicitamente quando não há cobrança.");button("Salvar configuração",()->{store.saveConfig(Rules.minute(value(open)),Rules.minute(value(close)),Rules.integer(value(hours),"Horas"),Rules.money(value(operation)),Rules.money(value(cleaning)),Rules.money(value(supplies)));menu();});}
 private void prices(){begin("Tabela de preços");EditText year=field("Ano *",Integer.toString(store.today().getYear()),InputType.TYPE_CLASS_NUMBER),turns=field("Turnos *","1",InputType.TYPE_CLASS_NUMBER);Spinner pct=select("Percentual *",new String[]{"100","75","50"},0);EditText amount=field("Valor (R$) *","");note("Referência inicial: tabela 2026 do desktop. Para outros anos, cadastre preços aprovados. Não há preço inventado automaticamente.");button("Salvar preço",()->{store.savePrice(Rules.integer(value(year),"Ano"),Rules.integer(value(turns),"Turnos"),Integer.parseInt(pct.getSelectedItem().toString()),Rules.money(value(amount)));prices();});for(JSONObject p:store.rows("SELECT * FROM prices ORDER BY year,turns,pct DESC"))note(p.optInt("year")+" · "+p.optInt("turns")+" turno(s) · "+p.optInt("pct")+"% · "+amount(p.optLong("amount")));}
 private void holiday(){begin("Feriados");final LocalDate[] day={selected};dayPicker(selected,d->day[0]=d);EditText name=field("Descrição *","");button("Salvar feriado",()->{store.saveHoliday(day[0],value(name));menu();});for(JSONObject h:store.rows("SELECT * FROM holidays ORDER BY day"))note(h.optString("day")+" · "+h.optString("name"));}
 private void quotas(){begin("Cotas de "+YearMonth.from(selected));note("Referência: mês da data selecionada na agenda. Cotas são por persona e por instalação; não são compartilhadas com o desktop. Mudanças na cota desta versão experimental recalculam os meses anteriores com o novo limite.");for(JSONObject p:store.rows("SELECT * FROM personas ORDER BY code")){title(p.optString("code")+" · "+p.optString("name"));if(p.isNull("quota")){note("Sem cota mensal.");continue;}int[] q=store.quota(p.optString("code"),YearMonth.from(selected));note("Total "+q[0]/60.0+" h · Usada "+q[1]/60.0+" h · Saldo "+q[2]/60.0+" h · Dívida "+q[3]/60.0+" h");if(store.admin())button("Alterar cota "+p.optString("code"),()->reason("Novo limite em horas inteiras",text->{store.saveQuota(p.optString("code"),Math.multiplyExact(Rules.integer(text,"Horas"),60));quotas();}));}}
 private void logs(){begin("Logs locais");note("Últimos 5000 eventos; somente códigos, IDs, versão e tipos de erro. Conteúdo de formulário, senhas e emails não são incluídos. Android pode interromper o processo sem aviso; eventos já salvos ficam no banco.");button("Exportar log sanitizado",()->export("inpetu-android-log.txt",store.logExport()));for(JSONObject e:store.rows("SELECT * FROM events ORDER BY id DESC LIMIT 200"))note(e.optString("time")+"\n"+e.optString("level")+" · "+e.optString("event")+" · v"+e.optString("version")+(e.optString("error_type").isEmpty()?"":"\n"+e.optString("error_type")));}
 private void export(String filename,String text){exportText=text;Intent intent=new Intent(Intent.ACTION_CREATE_DOCUMENT);intent.addCategory(Intent.CATEGORY_OPENABLE);intent.setType(filename.endsWith(".json")?"application/json":"text/plain");intent.putExtra(Intent.EXTRA_TITLE,filename);startActivityForResult(intent,11);}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(result!=RESULT_OK||data==null||data.getData()==null)return;attempt(()->{try{if(request==11){Rules.require(!exportText.isEmpty(),"Exportação interrompida. Entre novamente e gere o arquivo.");try(OutputStream out=getContentResolver().openOutputStream(data.getData(),"wt")){if(out==null)throw new IOException();out.write(exportText.getBytes(StandardCharsets.UTF_8));}exportText="";Toast.makeText(this,"Arquivo salvo",Toast.LENGTH_LONG).show();}else if(request==12){ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(InputStream input=getContentResolver().openInputStream(data.getData())){if(input==null)throw new IOException();byte[] block=new byte[8192];int n;while((n=input.read(block))!=-1){Rules.require(bytes.size()+n<=8*1024*1024,"Backup excede 8 MiB.");bytes.write(block,0,n);}}store.restore(new String(bytes.toByteArray(),StandardCharsets.UTF_8));menu();}}catch(IOException e){throw new IllegalStateException("Falha no arquivo",e);}});}
 @Override protected void onStop(){super.onStop();if(store!=null)try{store.event("INFO","APP_PAUSED",0,null);}catch(Exception ignored){}}
 @Override public void onBackPressed(){if(store!=null&&store.logged())agenda();else super.onBackPressed();}
}
